const convo = history.map(m => (m.role === 'user' ? 'Customer: ' : 'Assistant: ') + m.text).join('\n');
const now = DateTime.now().setZone(TZ);
return [{ json: {
  ok: !!(session && message), session_id: session, message, at: now.toISO(),
